CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uploaded_by_user_id BIGINT UNSIGNED NULL, name VARCHAR(255) NOT NULL, document_type ENUM('contract','invoice','quote','plan','receipt','identity','report','other') NOT NULL DEFAULT 'other', file_path VARCHAR(500) NOT NULL, mime_type VARCHAR(100) NOT NULL, file_size BIGINT UNSIGNED NOT NULL, related_module ENUM('btp','transport','agriculture','livestock','finance','agenda','users','other') NOT NULL DEFAULT 'other', related_type VARCHAR(100) NULL, related_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_documents_related (related_module,related_type,related_id), KEY idx_documents_type (document_type), CONSTRAINT chk_documents_size CHECK (file_size > 0), CONSTRAINT fk_documents_user FOREIGN KEY (uploaded_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
